import * as rx from 'rxjs';
import {SimplexReactor} from '@wfh/reactivizer';
import {tableForBase, createBase, BaseWidgetActions} from './terminal-widget';
import {createTerminalCanvas} from './terminal-canvas';

export function createScrollable<I extends BaseWidgetActions, LI extends typeof tableForBase>(component: SimplexReactor<I, LI>) {
  const comp = createBase();
  comp.config({});
  const {r, s} = comp;

  const canvas = createTerminalCanvas();
  r('configChange', s.configChange.pipe(
    rx.map(cfg => {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      const obj = [...cfg.values()].reduce((obj, key) => {
        obj[key] = s.opts[key];
        return obj;
      }, {} as Record<string, any>);
      canvas.config(obj);
    })
  ));

  return comp;
}
